    fn graph_edge_condition_from_str_roundtrip() {
        for cond in [
            GraphEdgeCondition::Pass,
            GraphEdgeCondition::Fail,
            GraphEdgeCondition::Always,
        ] {
            let s = cond.as_str();
            assert_eq!(GraphEdgeCondition::from_str(s), Some(cond));
        }
    }

